import github from "../mcp/tools/github/index.js";

/**
 * Executes a requested GitHub tool by mapping the function name to the target GitHub action.
 *
 * @param toolName - The name of the tool function called by Gemini
 * @param args - The arguments generated by Gemini matching the schema
 * @param githubToken - The user's temporary GitHub Personal Access Token from session
 * @returns Standardized execution result string or error message
 */
export async function executeTool(
  toolName: string,
  args: Record<string, any>,
  githubToken?: string,
): Promise<string> {
  try {
    switch (toolName) {
      // Branch Operations
      case "github_create_branch":
        return await github.createBranch(
          args.owner,
          args.repo,
          args.newBranchName,
          args.baseBranch ?? "main",
          githubToken,
        );

      case "github_list_branches":
        return await github.listBranches(args.owner, args.repo, githubToken);

      // Commit Operations
      case "github_get_commits":
        return await github.getCommits(
          args.owner,
          args.repo,
          args.baseBranch ?? "main",
          args.since,
          githubToken,
        );

      // Issue Operations
      case "github_create_issue":
        return await github.createIssues(
          args.owner,
          args.repo,
          args.title,
          args.body,
          githubToken,
        );

      case "github_get_issues":
        return await github.getIssues(
          args.owner,
          args.repo,
          args.mentioned,
          args.creator,
          githubToken,
        );

      case "github_create_comment_on_issue":
        return await github.createCommentOnIssue(
          args.owner,
          args.repo,
          Number(args.issueNumber),
          args.body,
          githubToken,
        );

      // Pull Request Operations
      case "github_list_prs":
        return await github.listPullRequests(
          args.owner,
          args.state,
          args.repo,
          args.sort,
          githubToken,
        );

      case "github_make_pull_request":
        return await github.makePullRequests(
          args.owner,
          args.repo,
          args.head,
          args.base,
          args.title,
          args.body,
          githubToken,
        );

      case "github_merge_pull_request":
        return await github.mergePullRequests(
          args.owner,
          args.repo,
          Number(args.pullNumber),
          args.commitTitle,
          args.commitMessage,
          githubToken,
        );

      // Release Operations
      case "github_list_releases":
        return await github.listReleases(
          args.owner,
          args.repo,
          args.page ? Number(args.page) : undefined,
          githubToken,
        );

      case "github_get_tag_releases":
        return await github.getTagReleases(
          args.owner,
          args.repo,
          args.tag,
          githubToken,
        );

      // Search Operations
      case "github_search_topics":
        return await github.searchTopics(
          args.q,
          args.page ? Number(args.page) : undefined,
          githubToken,
        );

      case "github_search_repos":
        return await github.searchRepos(
          args.q,
          args.page ? Number(args.page) : undefined,
          githubToken,
        );

      case "github_search_issues_and_prs":
        return await github.searchIssuesAndPRs(
          args.q,
          args.sort ?? "updated",
          args.page ? Number(args.page) : undefined,
          githubToken,
        );

      case "github_search_users":
        return await github.searchUsers(
          args.q,
          args.page ? Number(args.page) : undefined,
          githubToken,
        );

      // User & Repo Operations
      case "github_accept_repo_invite":
        return await github.acceptRepoInvite(
          args.owner,
          args.repo,
          Number(args.invitationId),
          githubToken,
        );

      case "github_create_repo":
        return await github.createRepo(
          args.name,
          args.description,
          Boolean(args.isPrivate),
          githubToken,
        );

      case "github_create_fork":
        return await github.createfork(args.owner, args.repo, githubToken);

      default:
        return `Error: Tool '${toolName}' was not recognized or is not supported.`;
    }
  } catch (error: any) {
    return `Execution Error in tool '${toolName}': ${error?.message || "Unknown error occurred"}`;
  }
}
